/** One unit's source travel, or undefined for a unit that came from somewhere else. */
export function sourceMuscleTravel(unit: string): SourceMuscleTravel | undefined {
  return SOURCE_MUSCLE_TRAVEL.find((r) => r.unit === unit);
}
